.sl-article-steps {
    background-color: var(--smartlearn-bg);
    padding-block: 3rem;
}
@media (min-width: 992px) {
    .sl-article-steps { padding-block: 6rem; }
}

.sl-article-steps .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-steps .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-steps .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-steps .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-steps .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-steps .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-article-steps .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

.sl-article-steps .sl-step-item {
    border: 1px solid transparent;
    transition: background-color 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}
.sl-article-steps .sl-step-btn { cursor: pointer; }
.sl-article-steps .sl-step-num { opacity: 0.5; line-height: 1; }
.sl-article-steps .sl-step-panel { display: none; }

.sl-article-steps .sl-step-item.active {
    background-color: var(--smartlearn-card-bg) !important;
    border-color: var(--smartlearn-card-border) !important;
    box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.06);
}
.sl-article-steps .sl-step-item.active .sl-step-num { opacity: 1; }
.sl-article-steps .sl-step-item.active .sl-step-panel {
    display: block;
    animation: sl-article-steps-fade 0.3s ease forwards;
}

.sl-article-steps .sl-step-media {
    opacity: 0;
    transition: opacity 0.45s ease, transform 0.45s ease;
    transform: scale(1.05);
    z-index: 1;
}
.sl-article-steps .sl-step-media.active {
    opacity: 1;
    transform: scale(1);
    z-index: 2;
}

@keyframes sl-article-steps-fade {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
    .sl-article-steps .sl-step-item,
    .sl-article-steps .sl-step-media { transition: none; transform: none; }
    .sl-article-steps .sl-step-item.active .sl-step-panel { animation: none; }
}

js:
(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-article-steps');
        sections.forEach(function(section, idx) {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            var uid = 'sl-steps-' + idx + '-' + Math.random().toString(36).slice(2, 7);
            var items = Array.prototype.slice.call(section.querySelectorAll('.sl-step-item'));
            var buttons = Array.prototype.slice.call(section.querySelectorAll('.sl-step-btn'));
            var images = Array.prototype.slice.call(section.querySelectorAll('.sl-step-media'));
            if (buttons.length === 0) return;

            items.forEach(function(item, i) {
                var panel = item.querySelector('.sl-step-panel');
                var btn = item.querySelector('.sl-step-btn');
                if (panel && btn) {
                    var panelId = uid + '-panel-' + i;
                    panel.id = panelId;
                    btn.setAttribute('aria-controls', panelId);
                }
            });

            function activateStep(step) {
                items.forEach(function(item) {
                    var isMatch = item.getAttribute('data-step') === step;
                    item.classList.toggle('active', isMatch);
                    var btn = item.querySelector('.sl-step-btn');
                    if (btn) btn.setAttribute('aria-expanded', isMatch ? 'true' : 'false');
                });
                images.forEach(function(img) {
                    img.classList.toggle('active', img.getAttribute('data-step') === step);
                });
            }

            buttons.forEach(function(btn, btnIndex) {
                btn.addEventListener('click', function() {
                    activateStep(btn.getAttribute('data-step'));
                });
                btn.addEventListener('keydown', function(e) {
                    var nextIdx = -1;
                    if (e.key === 'ArrowDown') nextIdx = (btnIndex + 1) % buttons.length;
                    else if (e.key === 'ArrowUp') nextIdx = (btnIndex - 1 + buttons.length) % buttons.length;
                    else if (e.key === 'Home') nextIdx = 0;
                    else if (e.key === 'End') nextIdx = buttons.length - 1;
                    if (nextIdx >= 0) {
                        e.preventDefault();
                        buttons[nextIdx].focus();
                        activateStep(buttons[nextIdx].getAttribute('data-step'));
                    }
                });
            });
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
